const I18N={
en:{tagline:"1 v 1 · Best of 3 rounds · Ladder of 7",intro:"Your frog enters the night pond colosseum. Chain combos, hurl rivals with a throw, spend your meter on a special — and finish the match with the POND SURGE. Beat all 7 rivals to face the Frog King.",yourName:"Your name",fight:"Fight the ladder",training:"Training mode",leaderboard:"Leaderboard",howto:"How to fight",howtoBody:"Drag the stick (or ◀ ▶) to move. LIGHT is fast, HEAVY hits hard — land HEAVY up close to THROW your rival. Tap-tap-tap builds combos. Hits charge your SPECIAL meter (2 charges max): unleash the POND BOLT at range. Hold BLOCK to guard — blocked hits barely scratch you, but throws break through. Win 2 rounds to take the match. Keyboard: ←/→ move, J light, K heavy, L block, U special.",allTime:"All time",thisWeek:"This week",loading:"Loading…",light:"Light",heavy:"Heavy",special:"Special",block:"Block",pause:"Pause",quit:"Quit",playAgain:"Fight again",backMenu:"Back to menu",round:"Round",finalRound:"Final round",fightWord:"FIGHT!",ko:"K.O.!",youWinRound:"You take the round!",rivalWinRound:"Rival takes the round!",timeUp:"TIME!",draw:"Draw round!",matchWon:"MATCH WON!",nextRival:"Next rival",champion:"COLOSSEUM CHAMPION!",championSub:"You beat every rival in the arena — the night pond is yours!",defeated:"KNOCKED OUT",defeatedSub:"Your frog is carried back to the lily pads. Train up and fight again!",scorePosted:"Score posted to the leaderboard.",scoreFailed:"Score could not be posted — the arena is busy.",noScores:"No scores yet — be the first!",boardFail:"Leaderboard unavailable right now.",guest:"Guest",houseFighter:"Arena Frog",ladderOf:"Rival {a} of {b}",specialReady:"POND BOLT READY!",finisher:"POND SURGE!",trainingWord:"TRAINING",trainingSub:"The dummy never falls. Quit any time — no score is posted.",throwWord:"THROW!",comboWord:"{a} HIT COMBO!"},
es:{tagline:"1 contra 1 · Mejor de 3 rondas · Escalera de 7",intro:"Tu rana entra al coliseo nocturno del estanque. Encadena combos, lanza a los rivales con un agarre, gasta tu medidor en un especial — y cierra el combate con la OLEADA DEL ESTANQUE. Vence a los 7 rivales y enfrenta al Rey Rana.",yourName:"Tu nombre",fight:"A la escalera",training:"Modo entrenamiento",leaderboard:"Clasificación",howto:"Cómo luchar",howtoBody:"Arrastra la palanca (o ◀ ▶) para moverte. LIGERO es rápido, PESADO pega fuerte — usa PESADO de cerca para LANZAR a tu rival. Toca-toca-toca crea combos. Los golpes cargan tu medidor ESPECIAL (2 cargas): suelta el RAYO DEL ESTANQUE a distancia. Mantén BLOQUEO para defenderte — pero los agarres lo atraviesan. Gana 2 rondas para llevarte el combate. Teclado: ←/→ mover, J ligero, K pesado, L bloqueo, U especial.",allTime:"Histórico",thisWeek:"Esta semana",loading:"Cargando…",light:"Ligero",heavy:"Pesado",special:"Especial",block:"Bloqueo",pause:"Pausa",quit:"Salir",playAgain:"Luchar otra vez",backMenu:"Volver al menú",round:"Ronda",finalRound:"¡Ronda final!",fightWord:"¡A LUCHAR!",ko:"¡K.O.!",youWinRound:"¡Ganas la ronda!",rivalWinRound:"El rival gana la ronda.",timeUp:"¡TIEMPO!",draw:"¡Ronda empatada!",matchWon:"¡COMBATE GANADO!",nextRival:"Siguiente rival",champion:"¡CAMPEÓN DEL COLISEO!",championSub:"Venciste a todos los rivales de la arena — ¡el estanque nocturno es tuyo!",defeated:"NOQUEADO",defeatedSub:"Tu rana vuelve a los nenúfares. ¡Entrena y pelea otra vez!",scorePosted:"Puntuación publicada en la clasificación.",scoreFailed:"No se pudo publicar — la arena está ocupada.",noScores:"Sin puntuaciones aún — ¡sé el primero!",boardFail:"Clasificación no disponible ahora.",guest:"Invitado",houseFighter:"Rana de la Arena",ladderOf:"Rival {a} de {b}",specialReady:"¡RAYO DEL ESTANQUE LISTO!",finisher:"¡OLEADA DEL ESTANQUE!",trainingWord:"ENTRENAMIENTO",trainingSub:"El muñeco nunca cae. Sal cuando quieras — no se publica puntuación.",throwWord:"¡AGARRE!",comboWord:"¡COMBO DE {a}!"},
pt:{tagline:"1 contra 1 · Melhor de 3 rounds · Escada de 7",intro:"Seu sapo entra no coliseu noturno da lagoa. Encadeie combos, arremesse rivais com um agarrão, gaste o medidor num especial — e feche a luta com a ONDA DA LAGOA. Vença os 7 rivais e encare o Rei Sapo.",yourName:"Seu nome",fight:"Para a escada",training:"Modo treino",leaderboard:"Classificação",howto:"Como lutar",howtoBody:"Arraste a alavanca (ou ◀ ▶) para mover. LEVE é rápido, PESADO bate forte — use PESADO de perto para ARREMESSAR o rival. Toque-toque-toque monta combos. Golpes carregam seu medidor ESPECIAL (2 cargas): solte o RAIO DA LAGOA à distância. Segure BLOQUEIO para defender — mas agarrões atravessam. Vença 2 rounds para levar a luta. Teclado: ←/→ mover, J leve, K pesado, L bloqueio, U especial.",allTime:"Geral",thisWeek:"Esta semana",loading:"Carregando…",light:"Leve",heavy:"Pesado",special:"Especial",block:"Bloqueio",pause:"Pausa",quit:"Sair",playAgain:"Lutar de novo",backMenu:"Voltar ao menu",round:"Round",finalRound:"Round final!",fightWord:"LUTEM!",ko:"K.O.!",youWinRound:"Você vence o round!",rivalWinRound:"O rival vence o round.",timeUp:"TEMPO!",draw:"Round empatado!",matchWon:"LUTA VENCIDA!",nextRival:"Próximo rival",champion:"CAMPEÃO DO COLISEU!",championSub:"Você venceu todos os rivais da arena — a lagoa noturna é sua!",defeated:"NOCAUTEADO",defeatedSub:"Seu sapo volta às vitórias-régias. Treine e lute de novo!",scorePosted:"Pontuação publicada na classificação.",scoreFailed:"Não foi possível publicar — a arena está ocupada.",noScores:"Sem pontuações ainda — seja o primeiro!",boardFail:"Classificação indisponível agora.",guest:"Convidado",houseFighter:"Sapo da Arena",ladderOf:"Rival {a} de {b}",specialReady:"RAIO DA LAGOA PRONTO!",finisher:"ONDA DA LAGOA!",trainingWord:"TREINO",trainingSub:"O boneco nunca cai. Saia quando quiser — sem pontuação.",throwWord:"ARREMESSO!",comboWord:"COMBO DE {a}!"},
fr:{tagline:"1 contre 1 · Meilleur des 3 manches · Échelle de 7",intro:"Votre grenouille entre dans le colisée nocturne de l'étang. Enchaînez les combos, projetez vos rivales, dépensez votre jauge en coup spécial — et terminez le match avec la VAGUE DE L'ÉTANG. Battez les 7 rivales pour affronter le Roi Grenouille.",yourName:"Votre nom",fight:"À l'échelle",training:"Mode entraînement",leaderboard:"Classement",howto:"Comment combattre",howtoBody:"Glissez le stick (ou ◀ ▶) pour bouger. LÉGER est rapide, LOURD frappe fort — LOURD au corps à corps PROJETTE la rivale. Tape-tape-tape enchaîne les combos. Les coups chargent votre jauge SPÉCIALE (2 charges) : lancez l'ÉCLAIR DE L'ÉTANG à distance. Maintenez BLOCAGE pour garder — mais les projections le traversent. Gagnez 2 manches pour le match. Clavier : ←/→ bouger, J léger, K lourd, L blocage, U spécial.",allTime:"Tout temps",thisWeek:"Cette semaine",loading:"Chargement…",light:"Léger",heavy:"Lourd",special:"Spécial",block:"Blocage",pause:"Pause",quit:"Quitter",playAgain:"Recombattre",backMenu:"Retour au menu",round:"Manche",finalRound:"Manche finale !",fightWord:"COMBAT !",ko:"K.O. !",youWinRound:"Vous gagnez la manche !",rivalWinRound:"La rivale gagne la manche.",timeUp:"TEMPS ÉCOULÉ !",draw:"Manche nulle !",matchWon:"MATCH GAGNÉ !",nextRival:"Rivale suivante",champion:"CHAMPION DU COLISÉE !",championSub:"Vous avez battu toutes les rivales de l'arène — l'étang nocturne est à vous !",defeated:"K.O.",defeatedSub:"Votre grenouille retourne aux nénuphars. Entraînez-vous et recombattez !",scorePosted:"Score publié au classement.",scoreFailed:"Score non publié — l'arène est occupée.",noScores:"Aucun score — soyez le premier !",boardFail:"Classement indisponible.",guest:"Invité",houseFighter:"Grenouille d'Arène",ladderOf:"Rivale {a} sur {b}",specialReady:"ÉCLAIR DE L'ÉTANG PRÊT !",finisher:"VAGUE DE L'ÉTANG !",trainingWord:"ENTRAÎNEMENT",trainingSub:"Le mannequin ne tombe jamais. Quittez quand vous voulez — aucun score.",throwWord:"PROJECTION !",comboWord:"COMBO ×{a} !"},
de:{tagline:"1 gegen 1 · Best of 3 Runden · Leiter mit 7",intro:"Dein Frosch betritt das nächtliche Teich-Kolosseum. Verkette Combos, wirf Rivalen mit einem Wurf, gib deinen Zähler für ein Spezial aus — und beende den Kampf mit der TEICHWELLE. Besiege alle 7 Rivalen und stelle dich dem Froschkönig.",yourName:"Dein Name",fight:"Die Leiter kämpfen",training:"Trainingsmodus",leaderboard:"Bestenliste",howto:"So kämpfst du",howtoBody:"Ziehe den Stick (oder ◀ ▶) zum Bewegen. LEICHT ist schnell, SCHWER trifft hart — SCHWER aus der Nähe WIRFT deinen Rivalen. Tipp-tipp-tipp baut Combos. Treffer laden deinen SPEZIAL-Zähler (2 Ladungen): Entfessle den TEICHBLITZ auf Distanz. Halte BLOCK zum Schützen — aber Würfe durchbrechen ihn. Gewinne 2 Runden für den Kampf. Tastatur: ←/→ bewegen, J leicht, K schwer, L Block, U Spezial.",allTime:"Alle Zeiten",thisWeek:"Diese Woche",loading:"Lädt…",light:"Leicht",heavy:"Schwer",special:"Spezial",block:"Block",pause:"Pause",quit:"Beenden",playAgain:"Nochmal kämpfen",backMenu:"Zurück zum Menü",round:"Runde",finalRound:"Finale Runde!",fightWord:"KAMPF!",ko:"K.O.!",youWinRound:"Du gewinnst die Runde!",rivalWinRound:"Der Rivale gewinnt die Runde.",timeUp:"ZEIT UM!",draw:"Runde unentschieden!",matchWon:"KAMPF GEWONNEN!",nextRival:"Nächster Rivale",champion:"KOLOSSEUM-CHAMPION!",championSub:"Du hast jeden Rivalen in der Arena besiegt — der Nachtteich gehört dir!",defeated:"AUSGENOCKT",defeatedSub:"Dein Frosch wird zu den Seerosen getragen. Trainiere und kämpfe erneut!",scorePosted:"Punkte in der Bestenliste eingetragen.",scoreFailed:"Punkte konnten nicht eingetragen werden.",noScores:"Noch keine Punkte — sei der Erste!",boardFail:"Bestenliste gerade nicht verfügbar.",guest:"Gast",houseFighter:"Arena-Frosch",ladderOf:"Rivale {a} von {b}",specialReady:"TEICHBLITZ BEREIT!",finisher:"TEICHWELLE!",trainingWord:"TRAINING",trainingSub:"Die Puppe fällt nie. Beende jederzeit — keine Punkte.",throwWord:"WURF!",comboWord:"{a}er-COMBO!"},
it:{tagline:"1 contro 1 · Al meglio di 3 round · Scala di 7",intro:"La tua rana entra nel colosseo notturno dello stagno. Incadena combo, lancia i rivali con una presa, spendi il misuratore per uno speciale — e chiudi il match con l'ONDA DELLO STAGNO. Sconfiggi i 7 rivali e affronta il Re Rana.",yourName:"Il tuo nome",fight:"Affronta la scala",training:"Modalità allenamento",leaderboard:"Classifica",howto:"Come combattere",howtoBody:"Trascina la levetta (o ◀ ▶) per muoverti. LEGGERO è veloce, PESANTE colpisce forte — PESANTE da vicino LANCIA il rivale. Tocca-tocca-tocca crea combo. I colpi caricano il misuratore SPECIALE (2 cariche): scaglia il FULMINE DELLO STAGNO a distanza. Tieni PARATA per difenderti — ma le prese la sfondano. Vinci 2 round per il match. Tastiera: ←/→ muovi, J leggero, K pesante, L parata, U speciale.",allTime:"Sempre",thisWeek:"Questa settimana",loading:"Caricamento…",light:"Leggero",heavy:"Pesante",special:"Speciale",block:"Parata",pause:"Pausa",quit:"Esci",playAgain:"Combatti ancora",backMenu:"Torna al menu",round:"Round",finalRound:"Round finale!",fightWord:"VIA!",ko:"K.O.!",youWinRound:"Vinci il round!",rivalWinRound:"Il rivale vince il round.",timeUp:"TEMPO SCADUTO!",draw:"Round pari!",matchWon:"MATCH VINTO!",nextRival:"Prossimo rivale",champion:"CAMPIONE DEL COLOSSEO!",championSub:"Hai battuto ogni rivale dell'arena — lo stagno notturno è tuo!",defeated:"MESSO K.O.",defeatedSub:"La tua rana torna alle ninfee. Allenati e combatti ancora!",scorePosted:"Punteggio pubblicato in classifica.",scoreFailed:"Punteggio non pubblicato — arena occupata.",noScores:"Nessun punteggio — sii il primo!",boardFail:"Classifica non disponibile ora.",guest:"Ospite",houseFighter:"Rana dell'Arena",ladderOf:"Rivale {a} di {b}",specialReady:"FULMINE DELLO STAGNO PRONTO!",finisher:"ONDA DELLO STAGNO!",trainingWord:"ALLENAMENTO",trainingSub:"Il manichino non cade mai. Esci quando vuoi — nessun punteggio.",throwWord:"PRESA!",comboWord:"COMBO DA {a}!"},

nl:{tagline:"1 tegen 1 · Beste van 3 rondes · Ladder van 7",intro:"Je kikker betreedt het nachtelijke vijvercolosseum. Keten combo's, gooi rivalen met een worp, geef je meter uit aan een special — en sluit de match af met de VIJVERGOLF. Versla alle 7 rivalen en daag de Kikkerkoning uit.",yourName:"Je naam",fight:"Beklim de ladder",training:"Trainingsmodus",leaderboard:"Ranglijst",howto:"Zo vecht je",howtoBody:"Sleep de stick (of ◀ ▶) om te bewegen. LICHT is snel, ZWAAR raakt hard — ZWAAR van dichtbij GOOIT je rivaal. Tik-tik-tik bouwt combo's. Treffers laden je SPECIAAL-meter (2 ladingen): ontketen de VIJVERFLITS op afstand. Houd BLOK vast om te verdedigen — maar worpen breken erdoor. Win 2 rondes voor de match. Toetsenbord: ←/→ bewegen, J licht, K zwaar, L blok, U speciaal.",allTime:"Allertijden",thisWeek:"Deze week",loading:"Laden…",light:"Licht",heavy:"Zwaar",special:"Speciaal",block:"Blok",pause:"Pauze",quit:"Stoppen",playAgain:"Opnieuw vechten",backMenu:"Terug naar menu",round:"Ronde",finalRound:"Laatste ronde!",fightWord:"VECHT!",ko:"K.O.!",youWinRound:"Je wint de ronde!",rivalWinRound:"De rivaal wint de ronde.",timeUp:"TIJD OM!",draw:"Ronde gelijk!",matchWon:"MATCH GEWONNEN!",nextRival:"Volgende rivaal",champion:"COLOSSEUMKAMPIOEN!",championSub:"Je versloeg elke rivaal in de arena — de nachtvijver is van jou!",defeated:"UITGESCHAKELD",defeatedSub:"Je kikker wordt terug naar de waterlelies gedragen. Train en vecht opnieuw!",scorePosted:"Score op de ranglijst geplaatst.",scoreFailed:"Score kon niet worden geplaatst.",noScores:"Nog geen scores — wees de eerste!",boardFail:"Ranglijst nu niet beschikbaar.",guest:"Gast",houseFighter:"Arenakikker",ladderOf:"Rivaal {a} van {b}",specialReady:"VIJVERFLITS KLAAR!",finisher:"VIJVERGOLF!",trainingWord:"TRAINING",trainingSub:"De pop valt nooit. Stop wanneer je wilt — geen score.",throwWord:"WORP!",comboWord:"{a}-TREFFER COMBO!"},
ru:{tagline:"1 на 1 · До 2 побед в раундах · Лестница из 7",intro:"Твоя лягушка выходит в ночной прудовый колизей. Связывай комбо, бросай соперников, трать шкалу на спецприём — и завершай матч ПРУДОВОЙ ВОЛНОЙ. Победи всех 7 соперников и встреться с Королём Лягушек.",yourName:"Твоё имя",fight:"В бой по лестнице",training:"Режим тренировки",leaderboard:"Таблица лидеров",howto:"Как сражаться",howtoBody:"Тяни стик (или ◀ ▶) для движения. ЛЁГКИЙ быстрый, ТЯЖЁЛЫЙ бьёт сильно — ТЯЖЁЛЫЙ вблизи БРОСАЕТ соперника. Тап-тап-тап строит комбо. Попадания заряжают шкалу СПЕЦПРИЁМА (2 заряда): выпускай ПРУДОВУЮ МОЛНИЮ на дистанции. Держи БЛОК для защиты — но броски его пробивают. Выиграй 2 раунда, чтобы взять матч. Клавиши: ←/→ движение, J лёгкий, K тяжёлый, L блок, U спецприём.",allTime:"За всё время",thisWeek:"Эта неделя",loading:"Загрузка…",light:"Лёгкий",heavy:"Тяжёлый",special:"Спец",block:"Блок",pause:"Пауза",quit:"Выйти",playAgain:"Ещё бой",backMenu:"В меню",round:"Раунд",finalRound:"Финальный раунд!",fightWord:"БОЙ!",ko:"НОКАУТ!",youWinRound:"Раунд твой!",rivalWinRound:"Раунд за соперником.",timeUp:"ВРЕМЯ ВЫШЛО!",draw:"Ничья в раунде!",matchWon:"МАТЧ ВЫИГРАН!",nextRival:"Следующий соперник",champion:"ЧЕМПИОН КОЛИЗЕЯ!",championSub:"Ты победил всех соперников арены — ночной пруд твой!",defeated:"НОКАУТ",defeatedSub:"Твою лягушку уносят обратно к кувшинкам. Тренируйся и в бой снова!",scorePosted:"Результат опубликован в таблице.",scoreFailed:"Не удалось опубликовать результат.",noScores:"Пока нет результатов — будь первым!",boardFail:"Таблица сейчас недоступна.",guest:"Гость",houseFighter:"Лягушка Арены",ladderOf:"Соперник {a} из {b}",specialReady:"ПРУДОВАЯ МОЛНИЯ ГОТОВА!",finisher:"ПРУДОВАЯ ВОЛНА!",trainingWord:"ТРЕНИРОВКА",trainingSub:"Манекен никогда не падает. Выходи в любой момент — без очков.",throwWord:"БРОСОК!",comboWord:"КОМБО ×{a}!"},
uk:{tagline:"1 на 1 · До 2 перемог у раундах · Драбина з 7",intro:"Твоя жаба виходить у нічний ставковий колізей. Зв'язуй комбо, кидай суперників, витрачай шкалу на спецприйом — і завершуй матч СТАВКОВОЮ ХВИЛЕЮ. Переможи всіх 7 суперників і зустрінься з Королем Жаб.",yourName:"Твоє ім'я",fight:"У бій драбиною",training:"Режим тренування",leaderboard:"Таблиця лідерів",howto:"Як битися",howtoBody:"Тягни стік (або ◀ ▶) для руху. ЛЕГКИЙ швидкий, ВАЖКИЙ б'є сильно — ВАЖКИЙ зблизька КИДАЄ суперника. Тап-тап-тап будує комбо. Влучання заряджають шкалу СПЕЦПРИЙОМУ (2 заряди): випускай СТАВКОВУ БЛИСКАВКУ на відстані. Тримай БЛОК для захисту — але кидки його пробивають. Виграй 2 раунди, щоб узяти матч. Клавіші: ←/→ рух, J легкий, K важкий, L блок, U спецприйом.",allTime:"За весь час",thisWeek:"Цей тиждень",loading:"Завантаження…",light:"Легкий",heavy:"Важкий",special:"Спец",block:"Блок",pause:"Пауза",quit:"Вийти",playAgain:"Ще бій",backMenu:"До меню",round:"Раунд",finalRound:"Фінальний раунд!",fightWord:"БІЙ!",ko:"НОКАУТ!",youWinRound:"Раунд твій!",rivalWinRound:"Раунд за суперником.",timeUp:"ЧАС ВИЙШОВ!",draw:"Нічия в раунді!",matchWon:"МАТЧ ВИГРАНО!",nextRival:"Наступний суперник",champion:"ЧЕМПІОН КОЛІЗЕЮ!",championSub:"Ти переміг усіх суперників арени — нічний ставок твій!",defeated:"НОКАУТ",defeatedSub:"Твою жабу несуть назад до латаття. Тренуйся і в бій знову!",scorePosted:"Результат опубліковано в таблиці.",scoreFailed:"Не вдалося опублікувати результат.",noScores:"Поки немає результатів — будь першим!",boardFail:"Таблиця зараз недоступна.",guest:"Гість",houseFighter:"Жаба Арени",ladderOf:"Суперник {a} з {b}",specialReady:"СТАВКОВА БЛИСКАВКА ГОТОВА!",finisher:"СТАВКОВА ХВИЛЯ!",trainingWord:"ТРЕНУВАННЯ",trainingSub:"Манекен ніколи не падає. Виходь будь-коли — без очок.",throwWord:"КИДОК!",comboWord:"КОМБО ×{a}!"},
tr:{tagline:"1'e 1 · 3 Raundun En İyisi · 7'li Merdiven",intro:"Kurbağan gece gölet kolezyumuna çıkıyor. Komboları bağla, rakipleri fırlat, ölçerini özele harca — ve maçı GÖLET DALGASI ile bitir. 7 rakibi de yen ve Kurbağa Kral ile yüzleş.",yourName:"Adın",fight:"Merdivene çık",training:"Antrenman modu",leaderboard:"Liderlik Tablosu",howto:"Nasıl dövüşülür",howtoBody:"Hareket için çubuğu sürükle (veya ◀ ▶). HAFİF hızlıdır, AĞIR sert vurur — AĞIR yakından rakibi FIRLATIR. Dokun-dokun-dokun kombo kurar. İsabetler ÖZEL ölçerini doldurur (2 yük): GÖLET ŞİMŞEĞİ'ni uzaktan sal. Korunmak için BLOK'u tut — ama fırlatmalar onu deler. Maçı almak için 2 raund kazan. Klavye: ←/→ hareket, J hafif, K ağır, L blok, U özel.",allTime:"Tüm zamanlar",thisWeek:"Bu hafta",loading:"Yükleniyor…",light:"Hafif",heavy:"Ağır",special:"Özel",block:"Blok",pause:"Duraklat",quit:"Çık",playAgain:"Tekrar dövüş",backMenu:"Menüye dön",round:"Raund",finalRound:"Final raundu!",fightWord:"DÖVÜŞ!",ko:"NAKAVT!",youWinRound:"Raundu aldın!",rivalWinRound:"Raundu rakip aldı.",timeUp:"SÜRE DOLDU!",draw:"Raund berabere!",matchWon:"MAÇ KAZANILDI!",nextRival:"Sonraki rakip",champion:"KOLEZYUM ŞAMPİYONU!",championSub:"Arenadaki her rakibi yendin — gece göleti senin!",defeated:"NAKAVT OLDUN",defeatedSub:"Kurbağan nilüferlere geri taşınıyor. Antrenman yap ve tekrar dövüş!",scorePosted:"Skor liderlik tablosuna yazıldı.",scoreFailed:"Skor yazılamadı — arena yoğun.",noScores:"Henüz skor yok — ilk sen ol!",boardFail:"Liderlik tablosu şu an kullanılamıyor.",guest:"Misafir",houseFighter:"Arena Kurbağası",ladderOf:"Rakip {a} / {b}",specialReady:"GÖLET ŞİMŞEĞİ HAZIR!",finisher:"GÖLET DALGASI!",trainingWord:"ANTRENMAN",trainingSub:"Manken asla düşmez. İstediğin an çık — skor yok.",throwWord:"FIRLAT!",comboWord:"{a} VURUŞLUK KOMBO!"},
ar:{tagline:"1 ضد 1 · الأفضل من 3 جولات · سلّم من 7",intro:"يدخل ضفدعك كولوسيوم البركة الليلي. اربط الكومبو، وارمِ المنافسين بقبضة، وأنفق عدّادك على حركة خاصة — واختم المباراة بموجة البركة. اهزم المنافسين السبعة وواجه ملك الضفادع.",yourName:"اسمك",fight:"قاتل في السلّم",training:"وضع التدريب",leaderboard:"لوحة المتصدرين",howto:"كيف تقاتل",howtoBody:"اسحب العصا (أو ◀ ▶) للتحرك. الخفيفة سريعة، والثقيلة تضرب بقوة — الثقيلة عن قرب ترمي المنافس. النقر المتكرر يبني الكومبو. الإصابات تشحن عدّاد الحركة الخاصة (شحنتان): أطلق صاعقة البركة من بعيد. اضغط مطولًا على الصد للحماية — لكن الرميات تخترقه. اربح جولتين للفوز بالمباراة. لوحة المفاتيح: ←/→ تحرك، J خفيفة، K ثقيلة، L صد، U خاصة.",allTime:"كل الأوقات",thisWeek:"هذا الأسبوع",loading:"جارٍ التحميل…",light:"خفيفة",heavy:"ثقيلة",special:"خاصة",block:"صد",pause:"إيقاف مؤقت",quit:"خروج",playAgain:"قاتل مجددًا",backMenu:"عودة إلى القائمة",round:"الجولة",finalRound:"الجولة الأخيرة!",fightWord:"قاتل!",ko:"ضربة قاضية!",youWinRound:"فزت بالجولة!",rivalWinRound:"المنافس يفوز بالجولة.",timeUp:"انتهى الوقت!",draw:"جولة متعادلة!",matchWon:"فزت بالمباراة!",nextRival:"المنافس التالي",champion:"بطل الكولوسيوم!",championSub:"هزمت كل منافسي الساحة — بركة الليل لك!",defeated:"سقط بالضربة القاضية",defeatedSub:"يُعاد ضفدعك إلى زنابق الماء. تدرّب وقاتل مجددًا!",scorePosted:"تم نشر النتيجة في اللوحة.",scoreFailed:"تعذّر نشر النتيجة — الساحة مشغولة.",noScores:"لا نتائج بعد — كن الأول!",boardFail:"اللوحة غير متاحة الآن.",guest:"ضيف",houseFighter:"ضفدع الساحة",ladderOf:"المنافس {a} من {b}",specialReady:"صاعقة البركة جاهزة!",finisher:"موجة البركة!",trainingWord:"تدريب",trainingSub:"الدمية لا تسقط أبدًا. اخرج متى شئت — لا نقاط.",throwWord:"رمية!",comboWord:"كومبو ×{a}!"},
hi:{tagline:"1 बनाम 1 · 3 राउंड में सर्वश्रेष्ठ · 7 की सीढ़ी",intro:"आपका मेंढक रात के तालाब कोलोसियम में उतरता है। कॉम्बो जोड़ें, प्रतिद्वंद्वियों को फेंकें, मीटर को स्पेशल पर खर्च करें — और मैच तालाब लहर से खत्म करें। सभी 7 प्रतिद्वंद्वियों को हराकर मेंढक राजा से भिड़ें।",yourName:"आपका नाम",fight:"सीढ़ी पर लड़ो",training:"प्रशिक्षण मोड",leaderboard:"लीडरबोर्ड",howto:"कैसे लड़ें",howtoBody:"चलने के लिए स्टिक खींचें (या ◀ ▶)। हल्का तेज़ है, भारी ज़ोरदार — भारी पास से प्रतिद्वंद्वी को फेंकता है। टैप-टैप-टैप कॉम्बो बनाता है। वार लगने से स्पेशल मीटर भरता है (2 चार्ज): दूर से तालाब बिजली छोड़ें। बचाव के लिए ब्लॉक दबाए रखें — लेकिन फेंक उसे तोड़ देता है। मैच जीतने के लिए 2 राउंड जीतें। कीबोर्ड: ←/→ चलें, J हल्का, K भारी, L ब्लॉक, U स्पेशल।",allTime:"सभी समय",thisWeek:"इस सप्ताह",loading:"लोड हो रहा है…",light:"हल्का",heavy:"भारी",special:"स्पेशल",block:"ब्लॉक",pause:"रोकें",quit:"छोड़ें",playAgain:"फिर लड़ो",backMenu:"मेनू पर वापस",round:"राउंड",finalRound:"अंतिम राउंड!",fightWord:"लड़ो!",ko:"नॉकआउट!",youWinRound:"राउंड आपका!",rivalWinRound:"राउंड प्रतिद्वंद्वी का।",timeUp:"समय समाप्त!",draw:"राउंड बराबर!",matchWon:"मैच जीता!",nextRival:"अगला प्रतिद्वंद्वी",champion:"कोलोसियम चैंपियन!",championSub:"आपने अखाड़े के हर प्रतिद्वंद्वी को हराया — रात का तालाब आपका है!",defeated:"नॉकआउट",defeatedSub:"आपका मेंढक कमल के पत्तों पर लौट आया। अभ्यास करें और फिर लड़ें!",scorePosted:"स्कोर लीडरबोर्ड पर पोस्ट हुआ।",scoreFailed:"स्कोर पोस्ट नहीं हुआ — अखाड़ा व्यस्त है।",noScores:"अभी कोई स्कोर नहीं — पहले बनें!",boardFail:"लीडरबोर्ड अभी उपलब्ध नहीं।",guest:"अतिथि",houseFighter:"अखाड़ा मेंढक",ladderOf:"प्रतिद्वंद्वी {a} / {b}",specialReady:"तालाब बिजली तैयार!",finisher:"तालाब लहर!",trainingWord:"प्रशिक्षण",trainingSub:"पुतला कभी नहीं गिरता। कभी भी छोड़ें — कोई स्कोर नहीं।",throwWord:"फेंक!",comboWord:"{a} हिट कॉम्बो!"},

id:{tagline:"1 lawan 1 · Terbaik dari 3 ronde · Tangga 7",intro:"Katakmu memasuki koloseum kolam malam. Rangkai kombo, lempar rival dengan bantingan, habiskan metermu untuk jurus spesial — dan akhiri pertandingan dengan GELOMBANG KOLAM. Kalahkan 7 rival dan hadapi Raja Katak.",yourName:"Namamu",fight:"Naiki tangga",training:"Mode latihan",leaderboard:"Papan Peringkat",howto:"Cara bertarung",howtoBody:"Seret stik (atau ◀ ▶) untuk bergerak. RINGAN cepat, BERAT memukul keras — BERAT dari dekat MELEMPAR rivalmu. Ketuk-ketuk-ketuk membangun kombo. Pukulan yang masuk mengisi meter SPESIAL (2 muatan): lepaskan PETIR KOLAM dari jauh. Tahan BLOK untuk bertahan — tapi lemparan menembusnya. Menangkan 2 ronde untuk merebut pertandingan. Keyboard: ←/→ bergerak, J ringan, K berat, L blok, U spesial.",allTime:"Sepanjang masa",thisWeek:"Minggu ini",loading:"Memuat…",light:"Ringan",heavy:"Berat",special:"Spesial",block:"Blok",pause:"Jeda",quit:"Keluar",playAgain:"Bertarung lagi",backMenu:"Kembali ke menu",round:"Ronde",finalRound:"Ronde final!",fightWord:"MULAI!",ko:"K.O.!",youWinRound:"Kamu memenangkan ronde!",rivalWinRound:"Rival memenangkan ronde.",timeUp:"WAKTU HABIS!",draw:"Ronde seri!",matchWon:"PERTANDINGAN DIMENANGKAN!",nextRival:"Rival berikutnya",champion:"JUARA KOLOSEUM!",championSub:"Kamu mengalahkan semua rival di arena — kolam malam ini milikmu!",defeated:"K.O.",defeatedSub:"Katakmu dibawa kembali ke daun teratai. Berlatihlah dan bertarung lagi!",scorePosted:"Skor terpasang di papan peringkat.",scoreFailed:"Skor tidak terpasang — arena sedang sibuk.",noScores:"Belum ada skor — jadilah yang pertama!",boardFail:"Papan peringkat tidak tersedia saat ini.",guest:"Tamu",houseFighter:"Katak Arena",ladderOf:"Rival {a} dari {b}",specialReady:"PETIR KOLAM SIAP!",finisher:"GELOMBANG KOLAM!",trainingWord:"LATIHAN",trainingSub:"Boneka tidak pernah jatuh. Keluar kapan saja — tanpa skor.",throwWord:"LEMPAR!",comboWord:"KOMBO {a} PUKULAN!"},
vi:{tagline:"1 đấu 1 · Thắng 2/3 hiệp · Thang 7 đối thủ",intro:"Ếch của bạn bước vào đấu trường ao đêm. Nối combo, quật đối thủ bằng cú ném, dùng thanh năng lượng cho chiêu đặc biệt — và kết thúc trận bằng SÓNG AO. Đánh bại 7 đối thủ để gặp Vua Ếch.",yourName:"Tên của bạn",fight:"Leo thang đối thủ",training:"Chế độ luyện tập",leaderboard:"Bảng xếp hạng",howto:"Cách chiến đấu",howtoBody:"Kéo cần (hoặc ◀ ▶) để di chuyển. NHẸ nhanh, NẶNG đánh mạnh — NẶNG ở cự ly gần sẽ NÉM đối thủ. Chạm-chạm-chạm tạo combo. Đòn trúng sạc thanh ĐẶC BIỆT (2 lượt): tung SÉT AO từ xa. Giữ ĐỠ để phòng thủ — nhưng cú ném phá vỡ nó. Thắng 2 hiệp để thắng trận. Bàn phím: ←/→ di chuyển, J nhẹ, K nặng, L đỡ, U đặc biệt.",allTime:"Mọi thời gian",thisWeek:"Tuần này",loading:"Đang tải…",light:"Nhẹ",heavy:"Nặng",special:"Đặc biệt",block:"Đỡ",pause:"Tạm dừng",quit:"Thoát",playAgain:"Đấu lại",backMenu:"Về menu",round:"Hiệp",finalRound:"Hiệp cuối!",fightWord:"CHIẾN!",ko:"K.O.!",youWinRound:"Bạn thắng hiệp!",rivalWinRound:"Đối thủ thắng hiệp.",timeUp:"HẾT GIỜ!",draw:"Hiệp hòa!",matchWon:"THẮNG TRẬN!",nextRival:"Đối thủ tiếp theo",champion:"NHÀ VÔ ĐỊCH ĐẤU TRƯỜNG!",championSub:"Bạn đã đánh bại mọi đối thủ trong đấu trường — ao đêm là của bạn!",defeated:"BỊ HẠ ĐO VÁN",defeatedSub:"Ếch của bạn được đưa về lá sen. Luyện tập và đấu lại!",scorePosted:"Điểm đã lên bảng xếp hạng.",scoreFailed:"Không đăng được điểm — đấu trường đang bận.",noScores:"Chưa có điểm — hãy là người đầu tiên!",boardFail:"Bảng xếp hạng hiện không khả dụng.",guest:"Khách",houseFighter:"Ếch Đấu Trường",ladderOf:"Đối thủ {a} / {b}",specialReady:"SÉT AO SẴN SÀNG!",finisher:"SÓNG AO!",trainingWord:"LUYỆN TẬP",trainingSub:"Hình nộm không bao giờ ngã. Thoát bất cứ lúc nào — không tính điểm.",throwWord:"NÉM!",comboWord:"COMBO {a} ĐÒN!"},
th:{tagline:"1 ต่อ 1 · ชนะ 2 ใน 3 ยก · บันได 7 คู่ต่อสู้",intro:"กบของคุณก้าวเข้าสู่โคลอสเซียมบึงยามค่ำคืน โจมตีเป็นคอมโบ เหวี่ยงคู่ต่อสู้ด้วยการทุ่ม ใช้เกจกับท่าพิเศษ — และปิดแมตช์ด้วยคลื่นบึง เอาชนะคู่ต่อสู้ทั้ง 7 ตัวเพื่อพบราชากบ",yourName:"ชื่อของคุณ",fight:"ไต่บันไดคู่ต่อสู้",training:"โหมดฝึกซ้อม",leaderboard:"ตารางคะแนน",howto:"วิธีต่อสู้",howtoBody:"ลากจอย (หรือ ◀ ▶) เพื่อเคลื่อนที่ เบาเร็ว หนักแรง — หนักระยะประชิดจะทุ่มคู่ต่อสู้ แตะ-แตะ-แตะสร้างคอมโบ การโจมตีโดนจะชาร์จเกจพิเศษ (2 ชาร์จ) ปล่อยสายฟ้าบึงจากระยะไกล กดบล็อกค้างเพื่อป้องกัน — แต่การทุ่มทะลุได้ ชนะ 2 ยกเพื่อชนะแมตช์ แป้นพิมพ์: ←/→ เคลื่อนที่ J เบา K หนัก L บล็อก U พิเศษ",allTime:"ตลอดกาล",thisWeek:"สัปดาห์นี้",loading:"กำลังโหลด…",light:"เบา",heavy:"หนัก",special:"พิเศษ",block:"บล็อก",pause:"หยุดชั่วคราว",quit:"ออก",playAgain:"สู้อีกครั้ง",backMenu:"กลับเมนู",round:"ยก",finalRound:"ยกสุดท้าย!",fightWord:"สู้!",ko:"น็อกเอาต์!",youWinRound:"คุณชนะยกนี้!",rivalWinRound:"คู่ต่อสู้ชนะยกนี้",timeUp:"หมดเวลา!",draw:"ยกเสมอ!",matchWon:"ชนะแมตช์!",nextRival:"คู่ต่อสู้ถัดไป",champion:"แชมป์โคลอสเซียม!",championSub:"คุณชนะคู่ต่อสู้ทุกคนในสังเวียน — บึงยามค่ำคืนเป็นของคุณ!",defeated:"ถูกน็อก",defeatedSub:"กบของคุณถูกพากลับไปยังใบบัว ฝึกซ้อมแล้วสู้ใหม่!",scorePosted:"โพสต์คะแนนขึ้นตารางแล้ว",scoreFailed:"โพสต์คะแนนไม่สำเร็จ — สังเวียนกำลังยุ่ง",noScores:"ยังไม่มีคะแนน — เป็นคนแรกเลย!",boardFail:"ตารางคะแนนไม่พร้อมตอนนี้",guest:"แขก",houseFighter:"กบสังเวียน",ladderOf:"คู่ต่อสู้ {a} จาก {b}",specialReady:"สายฟ้าบึงพร้อมแล้ว!",finisher:"คลื่นบึง!",trainingWord:"ฝึกซ้อม",trainingSub:"หุ่นไม่เคยล้ม ออกเมื่อไรก็ได้ — ไม่มีคะแนน",throwWord:"ทุ่ม!",comboWord:"คอมโบ {a} หมัด!"},
ko:{tagline:"1 대 1 · 3라운드 중 2선승 · 7인 래더",intro:"당신의 개구리가 밤 연못 콜로세움에 오릅니다. 콤보를 잇고, 던지기로 라이벌을 날리고, 게이지를 스페셜에 쓰세요 — 그리고 연못 파도로 경기를 마무리하세요. 라이벌 7명을 모두 이기면 개구리 왕과 맞붙습니다.",yourName:"당신의 이름",fight:"래더 도전",training:"트레이닝 모드",leaderboard:"리더보드",howto:"싸우는 법",howtoBody:"스틱을 드래그(또는 ◀ ▶)해 이동. 라이트는 빠르고 헤비는 강합니다 — 헤비를 가까이에서 맞히면 라이벌을 던집니다. 연타로 콤보를 쌓으세요. 명중시키면 스페셜 게이지가 찹니다(최대 2회): 연못 번개를 원거리에서 발사하세요. 블록을 누르고 있으면 방어 — 하지만 던지기는 뚫습니다. 2라운드를 이기면 매치 승리. 키보드: ←/→ 이동, J 라이트, K 헤비, L 블록, U 스페셜.",allTime:"전체",thisWeek:"이번 주",loading:"로딩 중…",light:"라이트",heavy:"헤비",special:"스페셜",block:"블록",pause:"일시정지",quit:"종료",playAgain:"다시 싸우기",backMenu:"메뉴로",round:"라운드",finalRound:"파이널 라운드!",fightWord:"파이트!",ko:"K.O.!",youWinRound:"라운드 승리!",rivalWinRound:"라이벌이 라운드를 가져갑니다.",timeUp:"시간 종료!",draw:"무승부 라운드!",matchWon:"매치 승리!",nextRival:"다음 라이벌",champion:"콜로세움 챔피언!",championSub:"경기장의 모든 라이벌을 이겼습니다 — 밤 연못은 당신의 것입니다!",defeated:"녹아웃",defeatedSub:"개구리가 연잎으로 돌아갑니다. 훈련하고 다시 싸우세요!",scorePosted:"점수가 리더보드에 등록됐습니다.",scoreFailed:"점수를 등록하지 못했습니다.",noScores:"아직 점수가 없습니다 — 첫 번째가 되세요!",boardFail:"리더보드를 지금 사용할 수 없습니다.",guest:"게스트",houseFighter:"아레나 개구리",ladderOf:"라이벌 {a} / {b}",specialReady:"연못 번개 준비 완료!",finisher:"연못 파도!",trainingWord:"트레이닝",trainingSub:"더미는 절대 쓰러지지 않습니다. 언제든 종료 — 점수 없음.",throwWord:"던지기!",comboWord:"{a}연타 콤보!"},
ja:{tagline:"1対1 · 3ラウンド先取 · 7人のラダー",intro:"あなたのカエルが夜の池コロッセオに登場。コンボをつなぎ、投げでライバルを吹き飛ばし、ゲージをスペシャルに使おう — フィニッシュはポンドサージ。全7ライバルを倒してカエル王に挑め。",yourName:"あなたの名前",fight:"ラダーに挑戦",training:"トレーニングモード",leaderboard:"リーダーボード",howto:"戦い方",howtoBody:"スティックをドラッグ（または◀ ▶）で移動。ライトは速く、ヘビーは強烈 — ヘビーを近距離で当てるとライバルを投げます。連打でコンボがつながります。ヒットでスペシャルゲージがたまります（最大2回）：ポンドボルトを遠距離で放とう。ブロック長押しでガード — ただし投げは貫通します。2ラウンド取ればマッチ勝利。キーボード：←/→移動、Jライト、Kヘビー、Lブロック、Uスペシャル。",allTime:"全期間",thisWeek:"今週",loading:"読み込み中…",light:"ライト",heavy:"ヘビー",special:"スペシャル",block:"ブロック",pause:"一時停止",quit:"終了",playAgain:"もう一度戦う",backMenu:"メニューに戻る",round:"ラウンド",finalRound:"ファイナルラウンド！",fightWord:"ファイト！",ko:"K.O.!",youWinRound:"ラウンド獲得！",rivalWinRound:"ライバルがラウンドを取った。",timeUp:"タイムアップ！",draw:"引き分けラウンド！",matchWon:"マッチ勝利！",nextRival:"次のライバル",champion:"コロッセオチャンピオン！",championSub:"アリーナの全ライバルを倒した — 夜の池はあなたのもの！",defeated:"ノックアウト",defeatedSub:"あなたのカエルは睡蓮の葉へ運ばれた。練習して再戦しよう！",scorePosted:"スコアをリーダーボードに投稿しました。",scoreFailed:"スコアを投稿できませんでした。",noScores:"まだスコアがありません — 最初の一人になろう！",boardFail:"リーダーボードは現在利用できません。",guest:"ゲスト",houseFighter:"アリーナフロッグ",ladderOf:"ライバル {a} / {b}",specialReady:"ポンドボルト準備完了！",finisher:"ポンドサージ！",trainingWord:"トレーニング",trainingSub:"ダミーは倒れません。いつでも終了可 — スコアなし。",throwWord:"投げ！",comboWord:"{a}ヒットコンボ！"},
zh:{tagline:"1 对 1 · 三局两胜 · 7 人天梯",intro:"你的青蛙走进夜池斗兽场。连起连招，用投技掀翻对手，把能量槽花在必杀上——再以池塘巨浪终结比赛。击败全部 7 名对手，迎战青蛙王。",yourName:"你的名字",fight:"挑战天梯",training:"训练模式",leaderboard:"排行榜",howto:"如何战斗",howtoBody:"拖动摇杆（或 ◀ ▶）移动。轻击快，重击狠——近身重击可以把对手投出去。连点打出连招。命中为必杀槽充能（最多 2 格）：远程释放池塘闪电。按住格挡防御——但投技可以破防。赢下 2 个回合即赢得比赛。键盘：←/→ 移动，J 轻击，K 重击，L 格挡，U 必杀。",allTime:"全部时间",thisWeek:"本周",loading:"加载中…",light:"轻击",heavy:"重击",special:"必杀",block:"格挡",pause:"暂停",quit:"退出",playAgain:"再战一场",backMenu:"返回菜单",round:"回合",finalRound:"最终回合！",fightWord:"开战！",ko:"击倒！",youWinRound:"你赢下这一回合！",rivalWinRound:"对手赢下这一回合。",timeUp:"时间到！",draw:"回合平局！",matchWon:"比赛胜利！",nextRival:"下一个对手",champion:"斗兽场冠军！",championSub:"你击败了竞技场的所有对手——夜池归你了！",defeated:"被击倒",defeatedSub:"你的青蛙被送回睡莲叶。训练后再战！",scorePosted:"成绩已发布到排行榜。",scoreFailed:"成绩发布失败——竞技场正忙。",noScores:"暂无成绩——来做第一名！",boardFail:"排行榜暂时不可用。",guest:"访客",houseFighter:"竞技场青蛙",ladderOf:"对手 {a} / {b}",specialReady:"池塘闪电就绪！",finisher:"池塘巨浪！",trainingWord:"训练",trainingSub:"假人永远不会倒下。随时退出——不计成绩。",throwWord:"投技！",comboWord:"{a} 连击！"}
};

const FC_OVR = {
en:{intro:"Your frog enters the night pond colosseum for a full 3D clash — best of 3 rounds. Chain jabs, hooks and slide kicks, fire directional specials, and at a full meter unleash the ULTIMATE. Beat all 7 rivals on the ladder to face the Frog King.",howtoBody:"Move with the floating joystick (or A/D and ◀ ▶). W jumps, S crouches, hold away or Shift to block. J = jab, K = hook, L = slide kick. U + direction fires a special (25 meter): ↑ launcher · ↓ sweep · → dash · ← orb. At a full 100 meter, U fires the ULTIMATE. Win 2 rounds to take the match, beat the rival to climb the ladder.",houseFighter:"House Frog"},
es:{intro:"Tu rana entra al coliseo del estanque nocturno para un choque 3D completo — al mejor de 3 rondas. Encadena jabs, ganchos y patadas deslizantes, lanza especiales direccionales y, con el medidor lleno, desata el DEFINITIVO. Vence a los 7 rivales de la escalera y enfrenta al Rey Rana.",howtoBody:"Muévete con la palanca flotante (o A/D y ◀ ▶). W salta, S se agacha, mantén atrás o Shift para bloquear. J = jab, K = gancho, L = patada deslizante. U + dirección lanza un especial (25 de medidor): ↑ elevador · ↓ barrido · → embestida · ← orbe. Con 100 de medidor, U lanza el DEFINITIVO. Gana 2 rondas para llevarte el combate y vence al rival para subir la escalera."},
pt:{intro:"Sua rã entra no coliseu do lago noturno para um confronto 3D completo — melhor de 3 rounds. Encadeie jabs, ganchos e chutes deslizantes, dispare especiais direcionais e, com o medidor cheio, solte o ULTIMATE. Vença os 7 rivais da escada e encare o Rei Sapo.",howtoBody:"Mova-se com o joystick flutuante (ou A/D e ◀ ▶). W pula, S agacha, segure para trás ou Shift para bloquear. J = jab, K = gancho, L = chute deslizante. U + direção dispara um especial (25 de medidor): ↑ lançador · ↓ varredura · → avanço · ← orbe. Com 100 de medidor, U dispara o ULTIMATE. Vença 2 rounds para ganhar a luta e suba na escada."},
fr:{intro:"Votre grenouille entre dans le colisée de l'étang nocturne pour un affrontement 3D complet — au meilleur des 3 rounds. Enchaînez jabs, crochets et coups de pied glissés, tirez des spéciaux directionnels et, jauge pleine, déclenchez l'ULTIME. Battez les 7 rivaux de l'échelle pour affronter le Roi Grenouille.",howtoBody:"Déplacez-vous avec le joystick flottant (ou A/D et ◀ ▶). W saute, S s'accroupit, maintenez arrière ou Maj pour bloquer. J = jab, K = crochet, L = coup de pied glissé. U + direction lance un spécial (25 de jauge) : ↑ lanceur · ↓ balayage · → ruée · ← orbe. À 100 de jauge, U déclenche l'ULTIME. Gagnez 2 rounds pour remporter le match et grimpez dans l'échelle."},
de:{intro:"Dein Frosch betritt das Nachtteich-Kolosseum zum vollen 3D-Duell — Best of 3 Runden. Verkette Jabs, Haken und Rutschtritte, feuere Richtungs-Speziale und entfessle bei voller Leiste das ULTIMATIVE. Besiege alle 7 Rivalen der Leiter und stelle dich dem Froschkönig.",howtoBody:"Bewege dich mit dem schwebenden Joystick (oder A/D und ◀ ▶). W springt, S duckt sich, weghalten oder Shift zum Blocken. J = Jab, K = Haken, L = Rutschtritt. U + Richtung feuert ein Spezial (25 Leiste): ↑ Launcher · ↓ Sweep · → Dash · ← Orb. Bei 100 Leiste startet U das ULTIMATIVE. Gewinne 2 Runden für den Kampf und steige die Leiter hinauf."},
it:{intro:"La tua rana entra nel colosseo dello stagno notturno per uno scontro 3D completo — al meglio dei 3 round. Concatena jab, ganci e calci scivolati, spara speciali direzionali e, a barra piena, scatena l'ULTRA. Batti i 7 rivali della scala e affronta il Re Rana.",howtoBody:"Muoviti con il joystick flottante (o A/D e ◀ ▶). W salta, S si accovaccia, tieni indietro o Maiusc per bloccare. J = jab, K = gancio, L = calcio scivolato. U + direzione spara uno speciale (25 di barra): ↑ lanciatore · ↓ spazzata · → scatto · ← sfera. A 100 di barra, U scatena l'ULTRA. Vinci 2 round per il match e scala la classifica."},
nl:{intro:"Je kikker betreedt het nachtelijke vijvercolosseum voor een volledige 3D-clash — beste van 3 rondes. Keten jabs, hoeken en glijtrappen, vuur directionele specials af en ontketen bij een volle meter de ULTIMATE. Versla alle 7 rivalen op de ladder en neem het op tegen de Kikkerkoning.",howtoBody:"Beweeg met de zwevende joystick (of A/D en ◀ ▶). W springt, S hurkt, houd weg of Shift om te blokkeren. J = jab, K = hoek, L = glijtrap. U + richting vuurt een special af (25 meter): ↑ launcher · ↓ sweep · → dash · ← orb. Bij 100 meter vuurt U de ULTIMATE af. Win 2 rondes voor de match en klim de ladder op."},
ru:{intro:"Ваша лягушка выходит в ночной прудовой колизей на полноценный 3D-поединок — до двух побед в раундах. Связывайте джебы, хуки и подкаты, стреляйте направленными спецатаками, а при полной шкале выпускайте УЛЬТИМЕЙТ. Победите всех 7 соперников по лестнице и встретьтесь с Королём лягушек.",howtoBody:"Двигайтесь плавающим джойстиком (или A/D и ◀ ▶). W — прыжок, S — присед, удерживайте «от себя» или Shift для блока. J = джеб, K = хук, L = подкат. U + направление — спецатака (25 шкалы): ↑ подброс · ↓ подсечка · → рывок · ← сфера. При 100 шкалы U запускает УЛЬТИМЕЙТ. Выиграйте 2 раунда, чтобы взять матч и подняться по лестнице."},
uk:{intro:"Ваша жаба виходить у нічний ставковий колізей на повноцінний 3D-поєдинок — до двох перемог у раундах. Зв'язуйте джеби, хуки та підкати, стріляйте напрямними спецприйомами, а за повної шкали випускайте УЛЬТИМЕЙТ. Переможіть усіх 7 суперників на драбині та зустріньтеся з Королем жаб.",howtoBody:"Рухайтесь плаваючим джойстиком (або A/D і ◀ ▶). W — стрибок, S — присід, тримайте «від себе» або Shift для блоку. J = джеб, K = хук, L = підкат. U + напрям — спецприйом (25 шкали): ↑ підкидання · ↓ підсічка · → ривок · ← сфера. За 100 шкали U запускає УЛЬТИМЕЙТ. Виграйте 2 раунди, щоб узяти матч і піднятися драбиною."},
tr:{intro:"Kurbağan, gece gölet kolezyumuna tam bir 3B kapışma için çıkıyor — 3 raundun en iyisi. Jab'leri, kroşeleri ve kayan tekmeleri bağla, yönlü özeller ateşle ve dolu ölçerde ULTİMATE'i serbest bırak. Merdivendeki 7 rakibi de yen ve Kurbağa Kral ile yüzleş.",howtoBody:"Yüzen çubukla (veya A/D ve ◀ ▶) hareket et. W zıplar, S çömelir, blok için geriyi basılı tut veya Shift. J = jab, K = kroşe, L = kayan tekme. U + yön özel ateşler (25 ölçer): ↑ fırlatıcı · ↓ süpürme · → atılma · ← küre. 100 ölçerde U, ULTİMATE'i ateşler. Maçı almak için 2 raund kazan ve merdiveni tırman."},
ar:{intro:"يدخل ضفدعك كولوسيوم البركة الليلية في مواجهة ثلاثية الأبعاد كاملة — الأفضل من 3 جولات. اربط اللكمات والخطافات والركلات المنزلقة، وأطلق الحركات الخاصة الاتجاهية، وعند امتلاء العدّاد أطلق الحركة القصوى. اهزم المنافسين السبعة في السلّم وواجه ملك الضفادع.",howtoBody:"تحرك بعصا التحكم العائمة (أو A/D و◀ ▶). W للقفز، S للانحناء، واضغط مطولًا بعيدًا أو Shift للصد. J = لكمة، K = خطاف، L = ركلة منزلقة. U + اتجاه يطلق حركة خاصة (25 عدّادًا): ↑ قاذف · ↓ كنس · → اندفاع · ← كرة. عند 100 عدّاد، U يطلق الحركة القصوى. اربح جولتين للفوز بالمباراة وتسلّق السلّم."},
hi:{intro:"आपका मेंढक रात के तालाब कोलोसियम में पूरे 3D मुक़ाबले के लिए उतरता है — 3 राउंड में सर्वश्रेष्ठ। जैब, हुक और स्लाइड किक जोड़ें, दिशात्मक स्पेशल चलाएँ, और पूरे मीटर पर अल्टीमेट छोड़ें। सीढ़ी के सभी 7 प्रतिद्वंद्वियों को हराकर मेंढक राजा से भिड़ें।",howtoBody:"फ़्लोटिंग जॉयस्टिक (या A/D और ◀ ▶) से चलें। W कूदता है, S झुकता है, ब्लॉक के लिए पीछे या Shift दबाए रखें। J = जैब, K = हुक, L = स्लाइड किक। U + दिशा से स्पेशल चलता है (25 मीटर): ↑ लॉन्चर · ↓ स्वीप · → डैश · ← ऑर्ब। 100 मीटर पर U अल्टीमेट चलाता है। मैच जीतने के लिए 2 राउंड जीतें और सीढ़ी चढ़ें।"},
id:{intro:"Katakmu memasuki koloseum kolam malam untuk bentrokan 3D penuh — terbaik dari 3 ronde. Rangkai jab, hook, dan tendangan geser, tembakkan spesial arah, dan saat meter penuh lepaskan ULTIMATE. Kalahkan 7 rival di tangga dan hadapi Raja Katak.",howtoBody:"Bergerak dengan joystick melayang (atau A/D dan ◀ ▶). W melompat, S jongkok, tahan menjauh atau Shift untuk blok. J = jab, K = hook, L = tendangan geser. U + arah menembakkan spesial (25 meter): ↑ peluncur · ↓ sapuan · → dash · ← orb. Pada 100 meter, U menembakkan ULTIMATE. Menangkan 2 ronde untuk merebut pertandingan dan naiki tangga."},
vi:{intro:"Ếch của bạn bước vào đấu trường ao đêm cho một trận 3D trọn vẹn — thắng 2/3 hiệp. Nối jab, móc và đá trượt, bắn chiêu đặc biệt theo hướng, và khi đầy thanh năng lượng hãy tung ULTIMATE. Đánh bại 7 đối thủ trên thang để gặp Vua Ếch.",howtoBody:"Di chuyển bằng cần điều khiển nổi (hoặc A/D và ◀ ▶). W nhảy, S cúi, giữ hướng ra xa hoặc Shift để đỡ. J = jab, K = móc, L = đá trượt. U + hướng bắn chiêu đặc biệt (25 năng lượng): ↑ hất tung · ↓ quét · → lao · ← cầu. Ở 100 năng lượng, U tung ULTIMATE. Thắng 2 hiệp để thắng trận và leo thang."},
th:{intro:"กบของคุณเข้าสู่โคลอสเซียมบึงยามค่ำคืนในการปะทะ 3D เต็มรูปแบบ — ชนะ 2 ใน 3 ยก ต่อย jab ฮุก และเตะสไลด์เป็นชุด ยิงท่าพิเศษตามทิศทาง และเมื่อเกจเต็มให้ปล่อย ULTIMATE เอาชนะคู่ต่อสู้ทั้ง 7 บนบันไดเพื่อพบราชากบ",howtoBody:"เคลื่อนที่ด้วยจอยลอย (หรือ A/D และ ◀ ▶) W กระโดด S หมอบ กดค้างถอยหลังหรือ Shift เพื่อบล็อก J = jab K = ฮุก L = เตะสไลด์ U + ทิศทางยิงท่าพิเศษ (เกจ 25): ↑ งัดลอย · ↓ กวาด · → พุ่ง · ← ลูกแก้ว ที่เกจ 100 U จะยิง ULTIMATE ชนะ 2 ยกเพื่อชนะแมตช์และไต่บันได"},
ko:{intro:"당신의 개구리가 밤 연못 콜로세움에 올라 완전한 3D 대결을 펼칩니다 — 3라운드 중 2선승. 잽, 훅, 슬라이드 킥을 잇고, 방향 스페셜을 쏘고, 게이지가 가득 차면 얼티밋을 해방하세요. 래더의 라이벌 7명을 모두 이기고 개구리 왕과 맞붙으세요.",howtoBody:"떠 있는 조이스틱(또는 A/D와 ◀ ▶)으로 이동. W 점프, S 웅크리기, 블록은 뒤로 홀드 또는 Shift. J = 잽, K = 훅, L = 슬라이드 킥. U + 방향은 스페셜 발사(게이지 25): ↑ 런처 · ↓ 스윕 · → 대시 · ← 오브. 게이지 100에서는 U가 얼티밋을 발사합니다. 2라운드를 이겨 경기를 가져가고 래더를 오르세요."},
ja:{intro:"あなたのカエルが夜の池コロッセオに登場し、フル3D対決 — 3ラウンド先取。ジャブ、フック、スライドキックをつなぎ、方向スペシャルを放ち、ゲージ満タンでアルティメットを解放しよう。ラダーの7ライバルを全て倒してカエル王に挑め。",howtoBody:"フローティングスティック（またはA/Dと◀ ▶）で移動。Wでジャンプ、Sでしゃがみ、後方長押しまたはShiftでブロック。J＝ジャブ、K＝フック、L＝スライドキック。U＋方向でスペシャル（ゲージ25）：↑ランチャー・↓スイープ・→ダッシュ・←オーブ。ゲージ100でUはアルティメットを放つ。2ラウンド取ってマッチを制し、ラダーを上ろう。"},
zh:{intro:"你的青蛙走进夜池斗兽场，展开完整的3D对决——三局两胜。连起刺拳、勾拳和滑踢，释放方向必杀，再在能量槽满时释放终极技。击败天梯上的全部7名对手，迎战青蛙王。",howtoBody:"用浮动摇杆（或 A/D 与 ◀ ▶）移动。W 跳跃，S 下蹲，按住远离键或 Shift 格挡。J = 刺拳，K = 勾拳，L = 滑踢。U + 方向释放必杀（25 能量）：↑ 升龙 · ↓ 横扫 · → 突进 · ← 能量球。能量 100 时，U 释放终极技。赢下 2 个回合即赢得比赛，并攀登天梯。"}
};
