const SPEC_NAMES = { rise: 'TOAD RISE', sweep: 'NIGHT SWEEP', dash: 'SWAMP DASH', orb: 'BOG ORB' };
function kitFromStats(st){
  const p = st.power, s = st.speed, r = st.range;
  return {
    dmgMul: 0.82 + p * 0.10, moveMul: 0.86 + s * 0.07,
    dashPow: 5.4 + s * 0.55 + r * 0.20, dashDmg: Math.round(10 + p * 1.6),
    riseDmg: Math.round(9 + p * 1.5), riseHop: 4.6 + s * 0.35,
    sweepPow: 5.0 + s * 0.55, sweepDmg: Math.round(8 + p * 1.4),
    orbDmg: Math.round(7 + r * 1.7), orbPow: 5.4 + r * 0.65, orbLife: 1.8 + r * 0.22,
    ultOrbDmg: 6, ultOrbCount: 3, meterGainMul: 0.95 + s * 0.03,
  };
}


