for (const L of Object.keys(FA2_KEYS)) if (I18N[L]) Object.assign(I18N[L], FA2_KEYS[L]);
let curLang = localStorage.getItem('farena2_lang') || 'en';
if (!I18N[curLang]) curLang = 'en';
function t(k){ return (I18N[curLang] && I18N[curLang][k]) || I18N.en[k] || k; }
function tf(k, a, b){ return t(k).replace('{a}', a).replace('{b}', b); }
function applyI18n(){
  document.documentElement.lang = curLang;
  const set = (id, v) => { const el = $(id); if (el) el.textContent = v; };
  set('intro', t('intro')); set('howtoBody', t('howtoBody'));
  set('fightBtn', t('fight')); set('pickLabel', t('pickFighter'));
  const ls = $('langSel'); if (ls) ls.value = curLang;
}
const langSel = $('langSel');
if (langSel) {
  for (const [code, name] of LANGS) {
    const o = document.createElement('option'); o.value = code; o.textContent = name;
    langSel.appendChild(o);
  }
  langSel.value = curLang;
  langSel.onchange = () => { curLang = langSel.value; localStorage.setItem('farena2_lang', curLang); applyI18n(); if (window.__fa2Hint) window.__fa2Hint(); };
}
applyI18n();
window.FC = {
  t, tf, SPEC_NAMES, kitFromStats,
  perks: { hp: false, timer: false },
  onChange() {},
  ensureManifest: async () => {},
  postScore: async () => false,
  loadBoard() {},
  playerName: () => '',
};
